<?php
if (!class_exists('MOL\\Frontend\\PublicSite')) { require __DIR__ . '/index.php'; return; }
try { $profile = MOL\Frontend\Routes::$profile ?? MOL\Frontend\PublicSite::profile((string) get_the_author_meta('user_nicename', get_queried_object_id())); } catch (MOL\Domain\Fault $error) { status_header(404); require __DIR__ . '/404.php'; return; }
get_header();
?>
<main id="mol-main" class="mol-site-main"><header class="mol-profile-header"><?php if ($profile['avatar_url']) : ?><img src="<?php echo esc_url($profile['avatar_url']); ?>" alt="" width="80" height="80"><?php endif; ?><div><p class="mol-kicker">المساهمون</p><h1 dir="auto"><?php echo esc_html($profile['display_name']); ?></h1><?php if ($profile['profile_tag']) : ?><p dir="auto"><?php echo esc_html($profile['profile_tag']); ?></p><?php endif; ?></div></header>
<p class="mol-bio" dir="auto"><?php echo esc_html($profile['bio']); ?></p><dl class="mol-profile-stats"><?php foreach (['works' => 'أعمال', 'chapters' => 'فصول', 'elements' => 'عناصر مترجمة'] as $key => $label) : ?><div><dd><?php echo (int) $profile['stats'][$key]; ?></dd><dt><?php echo esc_html($label); ?></dt></div><?php endforeach; ?></dl>
<section><h2>آخر المساهمات</h2><?php if (!$profile['recent_contributions']) : ?><p class="mol-empty">لا توجد مساهمات في فصول منشورة بعد.</p><?php else : ?><ol class="mol-chapter-list"><?php foreach ($profile['recent_contributions'] as $row) : $chapter = mol_get_chapter($row['chapter_id']); if (!$chapter) { continue; } ?><li><a href="<?php echo esc_url(mol_theme_chapter_link($chapter)); ?>"><strong dir="auto"><?php echo esc_html($row['work_title']); ?></strong><span>الفصل <?php echo esc_html($row['chapter_label']); ?></span><small><?php echo (int) $row['element_count']; ?> عنصر</small></a></li><?php endforeach; ?></ol><?php endif; ?></section></main><?php get_footer(); ?>
